DEFAULT = [E("Key Specification", "spec", "按器件类别填写", "decisive"), R("Rated Voltage", "vrated", "V", "3", "600", "important"), R("Rated Current", "irated", "A", "0.01", "50", "important"), E("Package / Mounting", "package", "SMD, THT, Module", "reference"), TEMP]

_COMPILED = [(re.compile(p), rows) for p, rows in TEMPLATES]


def params_for(path: str) -> list[dict]:
    """给定分类全路径（如 "集成电路（IC） > 线性 > 放大器 > 音频放大器"），返回参数模板副本。"""
    leaf = path.split(" > ")[-1]
    for pat, rows in _COMPILED:
        if pat.search(leaf) or pat.search(path):
            return [dict(r, source="seed") for r in rows]
    root = path.split(" > ")[0]
    return [dict(r, source="seed") for r in ROOT_FALLBACK.get(root, DEFAULT)]
